      rule_c9: { label: 'Kontrak riset, studi kelayakan, pengawasan, biro ilmiah dan teknik, biro dan perusahaan konsultasi (hanya kegiatan konsultasi)', note: '', valueLabel: 'Nilai kontrak' },
      rule_c10: { label: 'Kontrak yang mencakup desain, konsultasi, dan pengawasan selain pekerjaan', note: 'Sebagaimana disepakati awal dalam kontrak', valueLabel: 'Nilai kontrak' },
