      rule_c12: { label: 'Kontrak penerbitan, percetakan, distribusi, dan iklan di surat kabar dan majalah lokal (dan media iklan lainnya)', note: '', valueLabel: 'Nilai kontrak' },
      rule_c13: { label: 'Kontrak pelatihan di dalam Irak', note: '', valueLabel: 'Nilai kontrak' },
