      rule_c18: { label: 'Pembelian dari instansi pemerintah dengan penjualan langsung atau lelang', note: 'Kecuali pembelian langsung kendaraan dari Perusahaan Umum Perdagangan Kendaraan', valueLabel: 'Nilai kontrak' },
