      rule_c21: { label: 'Maskapai penerbangan dan biro perwakilan', note: 'Nilai yang dimasukkan adalah komisi, bukan total nilai kontrak', valueLabel: 'Komisi yang diterima' },
      rule_c22: { label: 'Perusahaan jasa keuangan yang menerbitkan kartu kredit (bila laporan keuangan ditolak)', note: '', valueLabel: 'Komisi yang diterima' },
