      rule_c26: { label: 'Perusahaan transportasi udara, darat, dan laut', note: '', valueLabel: 'Nilai kontrak' },
      rule_c27: { label: 'Perusahaan pengelola hotel, restoran, dan kompleks wisata', note: '', valueLabel: 'Nilai kontrak' },
      rule_c28: { label: 'Perusahaan yang mengorganisir dan mengelola penerimaan aplikasi visa dan transfer dokumen', note: 'Dari pendapatan', valueLabel: 'Nilai kontrak' },
