      rule_c30: { label: 'Perusahaan pengurusan kepabeanan dan ekspor', note: 'Jumlah tetap 15.000.000 dinar (laba bersih) atau sesuai pembukuan, mana yang lebih besar', valueLabel: 'Nilai kontrak' },
      rule_c31: { label: 'Perusahaan yang melaksanakan kontrak servis pesawat', note: 'Dari pendapatan', valueLabel: 'Nilai kontrak' },
      rule_c32: { label: 'Kontrak partisipasi antara perusahaan negara dan perusahaan swasta (lokal atau asing)', note: '', valueLabel: 'Nilai kontrak' },
