      rule_c37: { label: 'Hanya transfer uang (selain perseroan) — dengan komisi bank terkonfirmasi', note: 'Laba bersih = 50% selisih (pendapatan − komisi bank terkonfirmasi)', valueLabel: 'Nilai kontrak' },
