      rule_c1: { label: 'Peymanên tedarika materyalên îthal ên ji hêla heman bacdêr ve ku wan îthal kirine', note: 'Yê herî mezin ji dahata îthalatê an tedarikê tê sepandin', valueLabel: 'Nirxa peymanê' },
      rule_c2: { label: 'Peymanên tedarika materyalên ku ji bazara herêmî hatine kirîn', note: 'Ji bilî hinek tiştên madî (xwarinî/tibî/îbtîdaiyî) ji lîsteya îthalatê', valueLabel: 'Nirxa peymanê' },
      rule_c3: { label: 'Avakirin, parastin, boyaxkirin, tamîrkirin, sazkirin, bilindkirin, veguhestina rêwiyan, hesinkarî, necarî, barkirin, dakêşan, veguhestina tiştan, kirêya erebeyan û hemû kontarkat (ji bilî maddeyên xwarinî)', note: 'Heke materyal di peymanê de ji kar nayên cudakirin, bi 20% tên nirxandin', valueLabel: 'Nirxa peymanê' },
      rule_c4: { label: 'Peymanên tedarika maddeyên xwarinî ji hemû cûran', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c5: { label: 'Peymanên tedarika zêrrê xav îthal û berhemên zêrr (zêrrxemên îthal)', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c6: { label: 'Peymanên paqijkirinê', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c7: { label: 'Peymanên veguhestina/ barkirina/ dakêşana materyalên karta xwarinê ji bo nûnerên Pargîdaniya Giştî ya Bazirganiya Maddeyên Xwarinî', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c8: { label: 'Peymanên tedarika genimê zer û hemû çandiniyên çandinî', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c9: { label: 'Peymanên lêkolîn, lêkolînên mumkinbûnê, çavdêriyê, nivîsgehên zanistî û endazyariyê, nivîsgeh û pargîdaniyên şêwirmendiyê (tenê çalakiya şêwirmendiyê)', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c10: { label: 'Peymana ku li gel kar dihewîne dîzayn, şêwirmendî û çavdêriyê', note: 'Wek di peymanê de ji destpêkê ve hatiye tomarkirin', valueLabel: 'Nirxa peymanê' },
      rule_c11: { label: 'Peymanên ewlekariyê/parastinê', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c12: { label: 'Peymanên çapkirin, weşan, belavkirin û reklamê di rojname û kovarên herêmî de (û her medyayek reklamê ya din)', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c13: { label: 'Peymanên fêrbûnê li hundirê Iraqê', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c14: { label: 'Peymanên fêrbûnê li derveyî Iraqê', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c15: { label: 'Peymanên vejandina qurmên darê xurmê', note: 'Ji sedî nirxa peymanê', valueLabel: 'Nirxa peymanê' },
      rule_c16: { label: 'Peymanên tedarika an dabînkirina hêza kar', note: 'Ji bihayê peymanê', valueLabel: 'Nirxa peymanê' },
      rule_c17: { label: 'Peymanên werzişvanan (wek peyman)', note: 'Heke peyman meaşê mehane be, li vir nayê hesabkirin û dikeve bin jêgirtina rasterast a ji meaşê', valueLabel: 'Nirxa peymanê' },
      rule_c18: { label: 'Kirîna ji saziyên hikûmetê bi firotina rasterast an qumarê', note: 'Ji bilî kirîna rasterast a erebeyên ji Pargîdaniya Giştî ya Bazirganiya Erebeyan', valueLabel: 'Nirxa peymanê' },
      rule_c19: { label: 'Kirîna pelletên plastîk ji Pargîdaniya Giştî ya Pîşesaziya Petrokîmyayî an ji her hilberînerî', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c20: { label: 'Kirîna neftê an berhemên wê ji Wezareta Neftê ji bo firotina ji welatiyan re li derveyî stasyonên sotemeniyê', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c21: { label: 'Pargîdaniyên hewavaniyê û nivîsgehên nûnertiyê', note: 'Nirxa hatî nivîsîn komîsyon e ne nirxa tev a peymanê', valueLabel: 'Komîsyona wergirtî' },
      rule_c22: { label: 'Pargîdaniyên karûbarên darayî yên ku karta krediyê derdixin (dema raporta darayî tê redkirin)', note: '', valueLabel: 'Komîsyona wergirtî' },
      rule_c23: { label: 'Pargîdaniyên û navendên teknolojiya kompîtur, ragihandinê û înternetê', note: 'Piştî jêgirtina rêjeya medya û telekomûnîkasyonê', valueLabel: 'Nirxa peymanê' },
      rule_c24: { label: 'Kanalên satelît û weşangerên taybet', note: 'Ji dahata tev an raporta darayî, her ku mezintir be', valueLabel: 'Nirxa peymanê' },
      rule_c25: { label: 'Serîrêzên televîzyonê, bernameyên dîtbarî-bihîstbarî û fîlmên sînemayê', note: 'Ji dahata tev an defteran, her ku mezintir be', valueLabel: 'Nirxa peymanê' },
      rule_c26: { label: 'Pargîdaniyên veguhestina hewayî, axê û deryayî', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c27: { label: 'Pargîdaniyên rêvebirina otêl, xwaringeh û kompleksên geştyarî', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c28: { label: 'Pargîdaniyên ku wergirtina serlêdanên vîzayê û ragihandina belgenameyan rêxistin û rêvebir dikin', note: 'Ji dahatê', valueLabel: 'Nirxa peymanê' },
      rule_c29: { label: 'Pargîdaniyên ku pîşeya qanûnî dimeşînin', note: 'Ji dahata tev, bi dahata safî hindiktirîn 20.000.000 dînar an li gor defteran, her ku mezintir be', valueLabel: 'Nirxa peymanê' },
      rule_c30: { label: 'Pargîdaniyên gumrikê û îxracatê', note: 'Bihayê sabit 15.000.000 dînar (dahata safî) an li gor defteran, her ku mezintir be', valueLabel: 'Nirxa peymanê' },
      rule_c31: { label: 'Pargîdaniyên ku peymanên xizmeta balafiran pêk tînin', note: 'Ji dahatê', valueLabel: 'Nirxa peymanê' },
      rule_c32: { label: 'Peymanên beşdariyê di navbera pargîdaniyên dewletê û pargîdaniyên taybet (herêmî an biyanî) de', note: '', valueLabel: 'Nirxa peymanê' },
      rule_c33: { label: 'Peymanên Cost Plus', note: 'Dahata safî = mesref × rêjeya di peymanê de × 75%', valueLabel: 'Nirxa peymanê' },
      rule_c34: { label: 'Kovar û rojnameyên ji hemû cûran', note: 'Ji dahata tev an raporta darayî, her ku mezintir be', valueLabel: 'Nirxa peymanê' },
